constexpr pinned_bound flange_pose_from_tool_pose_bound{flange_pose_from_tool_pose_magnitude, flange_pose_from_tool_pose_linear, bound_standing::at_the_platform,
                                                        bound_standing::at_the_platform};
constexpr pinned_bound position_from_pose_bound{position_from_pose_magnitude, position_from_pose_linear, bound_standing::at_the_platform, bound_standing::at_the_platform};
constexpr pinned_bound orientation_from_pose_bound{orientation_from_pose_magnitude, orientation_from_pose_linear, bound_standing::at_the_platform, bound_standing::at_the_platform};
constexpr pinned_bound ik_solve_flange_pose_bound{ik_solve_flange_pose_magnitude, ik_solve_flange_pose_linear, bound_standing::above_the_platform, bound_standing::above_the_platform};
constexpr pinned_bound ik_solve_pose_bound{ik_solve_pose_magnitude, ik_solve_pose_linear, bound_standing::above_the_platform, bound_standing::above_the_platform};

constexpr bool is_identity(const std::array<double, 16> &pose)
{
    for(std::size_t entry = 0; entry < pose.size(); ++entry)
        if(pose[entry] != (entry % 5 == 0 ? 1.0 : 0.0))
            return false;
    return true;
}

constexpr bool joints_inside_limits(const frozen_chain &chain, const std::array<double, most_joints> &theta)
{
    for(std::size_t joint = 0; joint < most_joints; ++joint)
    {
        const bool held = joint < chain.joints ? chain.lower_position[joint] <= theta[joint] && theta[joint] <= chain.upper_position[joint] : theta[joint] == 0.0;
        if(!held)
            return false;
    }
    return true;
}

constexpr std::size_t solve_cases_of(std::size_t slot, std::size_t subject)
{
    return static_cast<std::size_t>(std::ranges::count_if(robot_solve_cases, [slot, subject](const robot_solve_case &row) { return row.slot == slot && row.subject == subject; }));
}

static_assert(pose_transformation_cases.size() == 8);
static_assert(std::ranges::all_of(pose_transformation_cases,
                                  [](const pose_transformation_case &row) { return last_row_affine(row.flange) && last_row_affine(row.offset) && last_row_affine(row.tool); }));
static_assert(robot_solve_cases.size() == 32);
static_assert(solve_cases_of(0, 0) == 8 && solve_cases_of(0, 1) == 8 && solve_cases_of(1, 0) == 8 && solve_cases_of(1, 1) == 8);
static_assert(std::ranges::all_of(robot_solve_cases, [](const robot_solve_case &row) { return joints_inside_limits(frozen_chains[row.subject], row.seed); }));
static_assert(std::ranges::all_of(robot_solve_cases, [](const robot_solve_case &row) { return row.slot != 0 || is_identity(row.offset); }));
static_assert(std::ranges::all_of(robot_solve_cases, [](const robot_solve_case &row) { return last_row_affine(row.target) && last_row_affine(row.offset); }));

inline Eigen::Matrix4d matrix_of(const std::array<double, 16> &pose)
{
    return Eigen::Map<const Eigen::Matrix<double, 4, 4, Eigen::RowMajor>>(pose.data());
}

